const raw = $json.candidates[0].content.parts[0].text;
const clean = raw.replace(/```json|```/g, '').trim();
const seo = JSON.parse(clean);

const jobId = $('Normalizza callback worker').item.json.job_id;
const bookTitle = $('Normalizza callback worker').item.json.book_title;

const testo = `COLORINGITALY — SEO LISTING
Job: ${jobId}
Tema: ${bookTitle}
Generato: ${new Date().toISOString()}

========================================
TITOLO ETSY (max 140 caratteri)
========================================
${seo.title}

========================================
TAG ETSY (13 tag)
========================================
${seo.tags.join(', ')}

========================================
DESCRIZIONE
========================================
${seo.description}
`;

return [{
  json: {
    job_id: jobId,
    seo_title: seo.title,
    seo_tags: seo.tags.join(', '),
    seo_description: seo.description,
    full_text: testo,
    filename: `${jobId}_seo_listing.txt`,
    local_path: `/srv/coloringitaly/jobs/${jobId}/${jobId}_seo_listing.txt`,
    minio_key: `${jobId}/${jobId}_seo_listing.txt`
  }
}];

const bookTitle = $('Normalizza callback worker').item.json.book_title || 'coloring book';

const prompt = `Sei un esperto SEO per Etsy specializzato in coloring book digitali. Genera il listing per un coloring book con tema: ${bookTitle}.

Rispondi SOLO con JSON valido senza markdown, senza backtick, senza spiegazioni:
{"title": "titolo SEO max 140 caratteri", "tags": ["tag1","tag2","tag3","tag4","tag5","tag6","tag7","tag8","tag9","tag10","tag11","tag12","tag13"], "description": "descrizione in inglese min 300 parole ottimizzata per Etsy che spiega il prodotto, i formati inclusi US Letter e A4, il numero di pagine, come scaricarlo e usarlo"}`;

const body = {
  contents: [{
    parts: [{
      text: prompt
    }]
  }]
};

return [{
  json: {
    gemini_body: JSON.stringify(body),
    job_id: $('Normalizza callback worker').item.json.job_id,
    book_title: bookTitle
  }
}];

const job_id = $json.job_id;
const outputs = $json.outputs || {};
const base_path = '/srv/coloringitaly/jobs/' + job_id + '/output/';

return Object.entries(outputs).map(([filename, size]) => ({
  json: {
    job_id,
    local_path: base_path + filename,
    minio_key: job_id + '/' + filename,
    fileName: filename,
    fileSize: size
  }
}));
